ALTER TABLE articles ADD COLUMN original_url VARCHAR(2048) NULL AFTER url_canonical, ADD COLUMN external_id VARCHAR(512) NULL AFTER original_url, ADD COLUMN publication_time_source VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'legacy_unknown' AFTER published_at, ADD COLUMN url_identity CHAR(64) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (SHA2(url_canonical, 256)) STORED, DROP INDEX uq_articles_url_canonical, ADD UNIQUE KEY uq_articles_url_identity (url_identity), ADD KEY idx_articles_source_external (source_id, external_id)
